  ('KWD', 'الدينار الكويتي', 'Kuwaiti Dinar', 'د.ك', 3),
  ('BHD', 'الدينار البحريني', 'Bahraini Dinar', 'د.ب', 3),
  ('OMR', 'الريال العماني', 'Omani Rial', 'ر.ع', 3),
