-- SmartBudget — reports on AI assistant answers ("Report this answer").
--
-- Google Play requires apps with generative AI to let users flag offensive
-- or wrong output. Users can only insert their own reports; the owner reviews
-- them in the Supabase dashboard (service role). Run once in the SQL editor.

create table if not exists public.ai_reports (
  id          bigint generated always as identity primary key,
  user_id     uuid not null default auth.uid()
              references auth.users(id) on delete cascade,
  reason      text not null check (reason in ('inaccurate', 'harmful', 'other')),
  answer      text not null check (char_length(answer) <= 8000),
  note        text check (char_length(note) <= 1000),
  created_at  timestamptz not null default now()
);

alter table public.ai_reports enable row level security;

drop policy if exists "ai_reports_insert_own" on public.ai_reports;
create policy "ai_reports_insert_own" on public.ai_reports
  for insert to authenticated
  with check (user_id = auth.uid());

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>> receipt_scanner.sql

-- ============================================================================
-- SmartBudget — Receipt Scanner: remove personal (BYOK) Gemini keys
-- ----------------------------------------------------------------------------
-- DGOTIX is the only AI provider: receipt scanning uses the server's own key
-- (GEMINI_API_KEY Edge Function secret) and every scan is metered against the
-- plan's cloud-OCR quota. Users no longer store personal keys, so the old
-- encrypted-key table is removed along with any keys it held.
--
-- Apply via the Supabase SQL editor or CLI. Safe to re-run.
-- ============================================================================

drop table if exists user_ai_keys;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>> security_hardening.sql

-- ============================================================================
-- SmartBudget — security hardening (run after the other files; safe to re-run)
-- ----------------------------------------------------------------------------
-- 1. Usage is reserved atomically before a model is called, so parallel
--    requests can't all pass the quota check, and a platform-wide monthly
--    ceiling caps total AI and cloud-OCR spend.
-- 2. Payment webhooks remember the time of the last event applied, so an
--    older event arriving late can't undo a newer one.
-- 3. Clients can't set the (unused) plan column on their own profile.
-- 4. A cloud backup can't exceed 10 MB.
-- Until this file is run, the Edge Functions keep working as before.
-- ============================================================================

-- ---- 1. Atomic usage reservation -------------------------------------------
create index if not exists ai_usage_monthly_month_idx on ai_usage_monthly(month);
create index if not exists ocr_usage_monthly_month_idx on ocr_usage_monthly(month);

-- Counts one AI request ('ai') or cloud scan ('ocr') for the user, unless the
-- user's limit (lifetime or this month) or the platform-wide monthly limit
-- (null = none) is reached. Returns 'ok', 'quota' or 'global'.
create or replace function public.reserve_usage(
  p_user uuid,
  p_kind text,
  p_month text,
  p_limit int,
  p_lifetime boolean,
  p_global_limit int
) returns text
language plpgsql security definer set search_path = public as $$
declare
  used  int;
  total bigint;
begin
  if p_kind not in ('ai', 'ocr') then
    raise exception 'unknown usage kind %', p_kind;
  end if;
  -- One reservation at a time per user and kind: parallel requests queue here.
  perform pg_advisory_xact_lock(hashtextextended(p_kind || ':' || p_user::text, 0));

  if p_kind = 'ai' then
    if p_lifetime then
      select requests into used from ai_usage_lifetime where user_id = p_user;
    else
      select requests into used from ai_usage_monthly
        where user_id = p_user and month = p_month;
    end if;
  else
    if p_lifetime then
      select scans into used from ocr_usage_lifetime where user_id = p_user;
    else
      select scans into used from ocr_usage_monthly
        where user_id = p_user and month = p_month;
    end if;
  end if;
  if coalesce(used, 0) >= p_limit then
    return 'quota';
  end if;

  if p_global_limit is not null then
    if p_kind = 'ai' then
      select coalesce(sum(requests), 0) into total from ai_usage_monthly
        where month = p_month;
    else
      select coalesce(sum(scans), 0) into total from ocr_usage_monthly
        where month = p_month;
    end if;
    if total >= p_global_limit then
      return 'global';
    end if;
  end if;

  if p_kind = 'ai' then
    insert into ai_usage_monthly as u (user_id, month, requests)
      values (p_user, p_month, 1)
      on conflict (user_id, month)
      do update set requests = u.requests + 1, updated_at = now();
    insert into ai_usage_lifetime as u (user_id, requests)
      values (p_user, 1)
      on conflict (user_id)
      do update set requests = u.requests + 1, updated_at = now();
  else
    insert into ocr_usage_monthly as u (user_id, month, scans)
      values (p_user, p_month, 1)
      on conflict (user_id, month)
      do update set scans = u.scans + 1, updated_at = now();
    insert into ocr_usage_lifetime as u (user_id, scans)
      values (p_user, 1)
      on conflict (user_id)
      do update set scans = u.scans + 1, updated_at = now();
  end if;
  return 'ok';
end $$;

-- Gives back a reservation whose request then failed (never below zero).
create or replace function public.release_usage(
  p_user uuid,
  p_kind text,
  p_month text
) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_kind = 'ai' then
    update ai_usage_monthly set requests = greatest(requests - 1, 0), updated_at = now()
      where user_id = p_user and month = p_month;
    update ai_usage_lifetime set requests = greatest(requests - 1, 0), updated_at = now()
      where user_id = p_user;
  elsif p_kind = 'ocr' then
    update ocr_usage_monthly set scans = greatest(scans - 1, 0), updated_at = now()
      where user_id = p_user and month = p_month;
    update ocr_usage_lifetime set scans = greatest(scans - 1, 0), updated_at = now()
      where user_id = p_user;
  end if;
end $$;

-- Only the Edge Functions (service role) may call them.
revoke all on function public.reserve_usage(uuid, text, text, int, boolean, int)
  from public, anon, authenticated;
revoke all on function public.release_usage(uuid, text, text)
  from public, anon, authenticated;
grant execute on function public.reserve_usage(uuid, text, text, int, boolean, int)
  to service_role;
grant execute on function public.release_usage(uuid, text, text)
  to service_role;

-- ---- 2. Webhook event ordering ---------------------------------------------
alter table subscriptions add column if not exists provider_event_at timestamptz;

-- ---- 3. Profile plan is server-only ----------------------------------------
-- Rows are created by the signup trigger; the user may change only these.
revoke insert, update on table profiles from anon, authenticated;
grant update (display_name, locale, theme, base_currency, updated_at)
  on table profiles to authenticated;

-- ---- 4. Backup size ---------------------------------------------------------
do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'user_backups_size'
  ) then
    alter table public.user_backups
      add constraint user_backups_size
      check (pg_column_size(data) <= 10485760) not valid;
  end if;
end $$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>> subscription_lifecycle.sql

-- ============================================================================
-- SmartBudget — subscription lifecycle (run after security_hardening.sql;
-- safe to re-run)
-- ----------------------------------------------------------------------------
-- A user can hold more than one subscription for a while (an upgrade bought
-- before the old plan ends, a PayPal plan next to a Paddle one). Each
-- subscription is therefore kept as its own row, and every payment webhook
-- goes through apply_subscription_event(), which, under a per-user lock:
--   1. updates that one subscription (ignoring events older than the last one
--      applied to it, and never moving it to another user);
--   2. sets the user's plan to the best plan among their active subscriptions,
--      so cancelling an old Basic subscription can't take away a running Pro;
--   3. refreshes the per-user summary in `subscriptions` that the app and the
--      Manage button read.
-- A full refund or chargeback takes away that subscription's access until a
-- new billing period is paid. The Edge Functions need this file: until it
-- runs, payment webhooks answer 500 and the providers retry them later.
-- ============================================================================

create table if not exists billing_subscriptions (
  provider                 text not null,
  provider_subscription_id text not null,
  user_id                  uuid not null references auth.users(id) on delete cascade,
  plan                     text not null default 'free',   -- plan of the price on it
  period                   text,
  -- active | trialing | past_due | paused | canceled | refunded | pending
  status                   text not null,
  provider_customer_id     text,
  current_period_end       timestamptz,
  cancel_at_period_end     boolean not null default false,
  provider_event_at        timestamptz,                    -- last event applied
  updated_at               timestamptz not null default now(),
  primary key (provider, provider_subscription_id)
);
create index if not exists billing_subscriptions_user_idx
  on billing_subscriptions(user_id);

-- Server only (service role): clients read the summary in `subscriptions`.
alter table billing_subscriptions enable row level security;
revoke all on table billing_subscriptions from anon, authenticated;

-- Subscriptions recorded before this file keep their state.
insert into billing_subscriptions (provider, provider_subscription_id, user_id,
  plan, period, status, provider_customer_id, current_period_end,
  cancel_at_period_end, provider_event_at)
select provider, provider_subscription_id, user_id, plan, period,
  case lower(coalesce(status, ''))
    when 'active' then 'active' when 'trialing' then 'trialing'
    when 'past_due' then 'past_due' when 'paused' then 'paused'
    when 'suspended' then 'paused' else 'canceled' end,
  provider_customer_id, current_period_end, cancel_at_period_end,
  provider_event_at
from subscriptions
where provider_subscription_id is not null
on conflict (provider, provider_subscription_id) do nothing;

-- Applies one verified provider event to one subscription. [p_user] is null
-- when the event names only the subscription (a refund, a payment); [p_plan],
-- [p_period], [p_period_end] and [p_cancel_at_period_end] are null when the
-- event doesn't carry them (kept as they are). [p_payment]: a payment for the
-- subscription just succeeded. Returns 'applied', 'stale' (older than the last
-- event applied), 'unknown_subscription' or 'user_mismatch'.
create or replace function public.apply_subscription_event(
  p_provider text,
  p_subscription_id text,
  p_user uuid,
  p_plan text,
  p_period text,
  p_status text,
  p_customer_id text,
  p_period_end timestamptz,
  p_cancel_at_period_end boolean,
  p_event_at timestamptz,
  p_payment boolean default false
) returns text
language plpgsql security definer set search_path = public as $$
declare
  cur  billing_subscriptions%rowtype;
  had  boolean;
  uid  uuid;
  st   text := lower(coalesce(p_status, ''));
  best text;
  prim billing_subscriptions%rowtype;
begin
  if p_provider not in ('paddle', 'paypal') or coalesce(p_subscription_id, '') = '' then
    raise exception 'bad subscription event';
  end if;
  if st not in ('active', 'trialing', 'past_due', 'paused', 'canceled', 'refunded', 'pending') then
    raise exception 'unknown subscription status %', p_status;
  end if;
  if p_plan is not null and p_plan not in ('free', 'basic', 'pro') then
    raise exception 'unknown plan %', p_plan;
  end if;

  select user_id into uid from billing_subscriptions
    where provider = p_provider and provider_subscription_id = p_subscription_id;
  uid := coalesce(uid, p_user);
  if uid is null then
    return 'unknown_subscription';
  end if;

  -- One change at a time per user: the plan below is computed from all of
  -- the user's subscriptions, so two webhooks must not interleave.
  perform pg_advisory_xact_lock(hashtextextended('billing:' || uid::text, 0));

  select * into cur from billing_subscriptions
    where provider = p_provider and provider_subscription_id = p_subscription_id;
  had := found;
  if had and (cur.user_id <> uid or (p_user is not null and p_user <> cur.user_id)) then
    -- A subscription stays with the account that bought it.
    return 'user_mismatch';
  end if;
  if had and cur.provider_event_at is not null and p_event_at is not null
     and p_event_at < cur.provider_event_at then
    return 'stale';
  end if;

  if p_payment then
    -- A payment revives a failed or refunded subscription, never a cancelled one.
    if not had then
      return 'unknown_subscription';
    end if;
    st := case when cur.status = 'canceled' then 'canceled' else 'active' end;
  elsif had and cur.status = 'refunded' and st in ('active', 'trialing')
        and (p_period_end is null or cur.current_period_end is null
             or p_period_end <= cur.current_period_end) then
    -- Refunded: access comes back only with a new paid period.
    st := 'refunded';
  end if;

  insert into billing_subscriptions as b (provider, provider_subscription_id,
    user_id, plan, period, status, provider_customer_id, current_period_end,
    cancel_at_period_end, provider_event_at, updated_at)
  values (p_provider, p_subscription_id, uid, coalesce(p_plan, 'free'), p_period,
    st, p_customer_id, p_period_end, coalesce(p_cancel_at_period_end, false),
    p_event_at, now())
  on conflict (provider, provider_subscription_id) do update set
    plan                 = coalesce(p_plan, b.plan),
    period               = coalesce(p_period, b.period),
    status               = st,
    provider_customer_id = coalesce(p_customer_id, b.provider_customer_id),
    current_period_end   = coalesce(p_period_end, b.current_period_end),
    cancel_at_period_end = coalesce(p_cancel_at_period_end, b.cancel_at_period_end),
    provider_event_at    = greatest(b.provider_event_at, p_event_at),
    updated_at           = now();

  -- The plan in force: the best plan among the active subscriptions.
  select plan into best from billing_subscriptions
    where user_id = uid and status in ('active', 'trialing') and plan in ('basic', 'pro')
    order by case plan when 'pro' then 2 else 1 end desc
    limit 1;
  insert into ai_entitlements as e (user_id, plan, updated_at)
    values (uid, coalesce(best, 'free'), now())
    on conflict (user_id) do update set plan = excluded.plan, updated_at = now();

  -- The summary the app shows and Manage opens: the subscription giving the
  -- plan; else one that still bills (payment failed, paused); else the latest.
  select * into prim from billing_subscriptions
    where user_id = uid
    order by
      (status in ('active', 'trialing')) desc,
      case when status in ('active', 'trialing') and plan = 'pro' then 2
           when status in ('active', 'trialing') and plan = 'basic' then 1
           else 0 end desc,
      (status in ('past_due', 'paused')) desc,
      current_period_end desc nulls last,
      provider_event_at desc nulls last
    limit 1;
  insert into subscriptions as s (user_id, provider, provider_customer_id,
    provider_subscription_id, plan, period, status, current_period_end,
    cancel_at_period_end, provider_event_at, updated_at)
  values (uid, prim.provider, prim.provider_customer_id,
    prim.provider_subscription_id,
    case when prim.status in ('active', 'trialing', 'past_due', 'paused')
         then prim.plan else 'free' end,
    prim.period, prim.status, prim.current_period_end, prim.cancel_at_period_end,
    prim.provider_event_at, now())
  on conflict (user_id) do update set
    provider                 = excluded.provider,
    provider_customer_id     = excluded.provider_customer_id,
    provider_subscription_id = excluded.provider_subscription_id,
    plan                     = excluded.plan,
    period                   = excluded.period,
    status                   = excluded.status,
    current_period_end       = excluded.current_period_end,
    cancel_at_period_end     = excluded.cancel_at_period_end,
    provider_event_at        = excluded.provider_event_at,
    updated_at               = now();

  return 'applied';
end $$;

-- Only the payment webhooks (service role) may call it.
revoke all on function public.apply_subscription_event(text, text, uuid, text,
  text, text, text, timestamptz, boolean, timestamptz, boolean)
  from public, anon, authenticated;
grant execute on function public.apply_subscription_event(text, text, uuid, text,
  text, text, text, timestamptz, boolean, timestamptz, boolean)
  to service_role;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>> abuse_limits.sql

-- ============================================================================
-- SmartBudget — limits against mass sign-ups (run after
-- subscription_lifecycle.sql; safe to re-run)
-- ----------------------------------------------------------------------------
-- Signing up is free, so someone can script many accounts. IP limits alone
-- don't stop that (accounts can come from many addresses), so the limits here
-- are per account and per kind of account:
--   1. Daily caps per account on AI answers and cloud scans, on top of the
--      monthly or lifetime allowance.
--   2. Shares of the platform's monthly AI/scan capacity: accounts that don't
--      pay share at most part of it, and accounts younger than a week (or not
--      confirmed) a smaller part. A crowd of fake accounts can use up only
--      its share; paying users keep the rest.
--   3. Per-account rate limits for the other costly functions (checkout,
--      subscription management, account deletion).
--   4. AI-answer reports: at most 20 per account per day.
--   5. Cloud backups of accounts younger than a week: at most 2 MB.
-- The Edge Functions choose the numbers (supabase/functions/_shared/quota.ts).
-- Until this file runs they keep the previous limits.
-- ============================================================================

-- ---- Counters (server only) -------------------------------------------------
create table if not exists usage_daily (
  user_id uuid not null references auth.users(id) on delete cascade,
  kind    text not null,                 -- 'ai' | 'ocr'
  day     date not null,
  count   int  not null default 0,
  primary key (user_id, kind, day)
);
create table if not exists usage_pools (
  kind  text not null,                   -- 'ai' | 'ocr'
  month text not null,                   -- 'YYYY-MM'
  pool  text not null,                   -- 'unpaid' | 'new'
  count int  not null default 0,
  primary key (kind, month, pool)
);
create table if not exists rate_limits (
  user_id      uuid not null references auth.users(id) on delete cascade,
  bucket       text not null,
  window_start timestamptz not null,
  count        int  not null default 0,
  primary key (user_id, bucket, window_start)
);
alter table usage_daily enable row level security;
alter table usage_pools enable row level security;
alter table rate_limits enable row level security;
revoke all on table usage_daily from anon, authenticated;
revoke all on table usage_pools from anon, authenticated;
revoke all on table rate_limits from anon, authenticated;

-- ---- Usage reservation, now with daily caps and shares -----------------------
-- Replaces the version in security_hardening.sql (same name; the new
-- arguments are optional).
drop function if exists public.reserve_usage(uuid, text, text, int, boolean, int);
drop function if exists public.release_usage(uuid, text, text);

-- Counts one AI request ('ai') or cloud scan ('ocr') for the user, unless a
-- limit is reached. Returns 'ok', 'quota' (the user's allowance), 'daily'
-- (the user's daily cap), 'global' (the platform's monthly limit) or 'pool'
-- (the monthly share for this kind of account: [p_pool] is 'paid', 'unpaid'
-- or 'new'; a 'new' request counts in both the 'new' and 'unpaid' shares).
create or replace function public.reserve_usage(
  p_user uuid,
  p_kind text,
  p_month text,
  p_limit int,
  p_lifetime boolean,
  p_global_limit int,
  p_daily_limit int default null,
  p_pool text default null,
  p_unpaid_limit int default null,
  p_new_limit int default null
) returns text
language plpgsql security definer set search_path = public as $$
declare
  used  int;
  total bigint;
  today date := (now() at time zone 'utc')::date;
begin
  if p_kind not in ('ai', 'ocr') then
    raise exception 'unknown usage kind %', p_kind;
  end if;
  if p_pool is not null and p_pool not in ('paid', 'unpaid', 'new') then
    raise exception 'unknown pool %', p_pool;
  end if;
  -- One reservation at a time per user and kind: parallel requests queue here.
  perform pg_advisory_xact_lock(hashtextextended(p_kind || ':' || p_user::text, 0));

  if p_kind = 'ai' then
    if p_lifetime then
      select requests into used from ai_usage_lifetime where user_id = p_user;
    else
      select requests into used from ai_usage_monthly
        where user_id = p_user and month = p_month;
    end if;
  else
    if p_lifetime then
      select scans into used from ocr_usage_lifetime where user_id = p_user;
    else
      select scans into used from ocr_usage_monthly
        where user_id = p_user and month = p_month;
    end if;
  end if;
  if coalesce(used, 0) >= p_limit then
    return 'quota';
  end if;

  if p_daily_limit is not null then
    select count into used from usage_daily
      where user_id = p_user and kind = p_kind and day = today;
    if coalesce(used, 0) >= p_daily_limit then
      return 'daily';
    end if;
  end if;

  if p_global_limit is not null then
    if p_kind = 'ai' then
      select coalesce(sum(requests), 0) into total from ai_usage_monthly
        where month = p_month;
    else
      select coalesce(sum(scans), 0) into total from ocr_usage_monthly
        where month = p_month;
    end if;
    if total >= p_global_limit then
      return 'global';
    end if;
  end if;

  if p_pool in ('unpaid', 'new') then
    -- The shares are shared by many users: one change at a time.
    perform pg_advisory_xact_lock(hashtextextended('pool:' || p_kind || ':' || p_month, 0));
    if p_unpaid_limit is not null then
      select count into used from usage_pools
        where kind = p_kind and month = p_month and pool = 'unpaid';
      if coalesce(used, 0) >= p_unpaid_limit then
        return 'pool';
      end if;
    end if;
    if p_pool = 'new' and p_new_limit is not null then
      select count into used from usage_pools
        where kind = p_kind and month = p_month and pool = 'new';
      if coalesce(used, 0) >= p_new_limit then
        return 'pool';
      end if;
    end if;
    insert into usage_pools as p (kind, month, pool, count)
      values (p_kind, p_month, 'unpaid', 1)
      on conflict (kind, month, pool) do update set count = p.count + 1;
    if p_pool = 'new' then
      insert into usage_pools as p (kind, month, pool, count)
        values (p_kind, p_month, 'new', 1)
        on conflict (kind, month, pool) do update set count = p.count + 1;
    end if;
  end if;

  if p_kind = 'ai' then
    insert into ai_usage_monthly as u (user_id, month, requests)
      values (p_user, p_month, 1)
      on conflict (user_id, month)
      do update set requests = u.requests + 1, updated_at = now();
    insert into ai_usage_lifetime as u (user_id, requests)
      values (p_user, 1)
      on conflict (user_id)
      do update set requests = u.requests + 1, updated_at = now();
  else
    insert into ocr_usage_monthly as u (user_id, month, scans)
      values (p_user, p_month, 1)
      on conflict (user_id, month)
      do update set scans = u.scans + 1, updated_at = now();
    insert into ocr_usage_lifetime as u (user_id, scans)
      values (p_user, 1)
      on conflict (user_id)
      do update set scans = u.scans + 1, updated_at = now();
  end if;
  insert into usage_daily as d (user_id, kind, day, count)
    values (p_user, p_kind, today, 1)
    on conflict (user_id, kind, day) do update set count = d.count + 1;
  -- Days that no longer count.
  delete from usage_daily where user_id = p_user and kind = p_kind and day < today - 7;
  return 'ok';
end $$;

-- Gives back a reservation whose request then failed (never below zero).
create or replace function public.release_usage(
  p_user uuid,
  p_kind text,
  p_month text,
  p_pool text default null
) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_kind = 'ai' then
    update ai_usage_monthly set requests = greatest(requests - 1, 0), updated_at = now()
      where user_id = p_user and month = p_month;
    update ai_usage_lifetime set requests = greatest(requests - 1, 0), updated_at = now()
      where user_id = p_user;
  elsif p_kind = 'ocr' then
    update ocr_usage_monthly set scans = greatest(scans - 1, 0), updated_at = now()
      where user_id = p_user and month = p_month;
    update ocr_usage_lifetime set scans = greatest(scans - 1, 0), updated_at = now()
      where user_id = p_user;
  else
    return;
  end if;
  update usage_daily set count = greatest(count - 1, 0)
    where user_id = p_user and kind = p_kind and day = (now() at time zone 'utc')::date;
  if p_pool in ('unpaid', 'new') then
    update usage_pools set count = greatest(count - 1, 0)
      where kind = p_kind and month = p_month
        and (pool = 'unpaid' or (p_pool = 'new' and pool = 'new'));
  end if;
end $$;

-- ---- Per-account rate limits ----------------------------------------------------
-- Counts one call in [p_bucket] for the user; true while the user has made at
-- most [p_max] calls in the current window of [p_window_s] seconds.
create or replace function public.rate_limit_hit(
  p_user uuid,
  p_bucket text,
  p_window_s int,
  p_max int
) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  win timestamptz := to_timestamp(floor(extract(epoch from now()) / p_window_s) * p_window_s);
  n   int;
begin
  insert into rate_limits as r (user_id, bucket, window_start, count)
    values (p_user, p_bucket, win, 1)
    on conflict (user_id, bucket, window_start) do update set count = r.count + 1
    returning count into n;
  delete from rate_limits
    where user_id = p_user and bucket = p_bucket and window_start < win;
  return n <= p_max;
end $$;

revoke all on function public.reserve_usage(uuid, text, text, int, boolean, int, int, text, int, int)
  from public, anon, authenticated;
revoke all on function public.release_usage(uuid, text, text, text)
  from public, anon, authenticated;
revoke all on function public.rate_limit_hit(uuid, text, int, int)
  from public, anon, authenticated;
grant execute on function public.reserve_usage(uuid, text, text, int, boolean, int, int, text, int, int)
  to service_role;
grant execute on function public.release_usage(uuid, text, text, text)
  to service_role;
grant execute on function public.rate_limit_hit(uuid, text, int, int)
  to service_role;

-- ---- AI-answer reports: at most 20 per account per day ------------------------
create index if not exists ai_reports_user_created_idx on ai_reports(user_id, created_at);
create or replace function public.ai_reports_daily_cap()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (select count(*) from ai_reports
      where user_id = new.user_id and created_at > now() - interval '1 day') >= 20 then
    raise exception 'too many reports today' using errcode = '54000';
  end if;
  return new;
end $$;
revoke all on function public.ai_reports_daily_cap() from public, anon, authenticated;
drop trigger if exists ai_reports_daily_cap on ai_reports;
create trigger ai_reports_daily_cap before insert on ai_reports
  for each row execute function public.ai_reports_daily_cap();

-- ---- Cloud backups of new accounts: at most 2 MB --------------------------------
create or replace function public.user_backups_new_account_size()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if pg_column_size(new.data) > 2 * 1024 * 1024 and exists (
       select 1 from auth.users
       where id = new.user_id and created_at > now() - interval '7 days') then
    raise exception 'backup too large for a new account' using errcode = '54000';
  end if;
  return new;
end $$;
revoke all on function public.user_backups_new_account_size() from public, anon, authenticated;
drop trigger if exists user_backups_new_account_size on user_backups;
create trigger user_backups_new_account_size before insert or update on user_backups
  for each row execute function public.user_backups_new_account_size();

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>> sync.sql

-- ============================================================================
-- SmartBudget — automatic sync between devices (run after abuse_limits.sql;
-- safe to re-run)
-- ----------------------------------------------------------------------------
-- The app keeps one sync document per account in user_backups (record-level
-- changes and deletions; see lib/features/sync). A version number makes each
-- upload conditional: a device writes only over the version it merged with,
-- so two devices syncing at the same moment can't overwrite each other (the
-- second one merges again and retries). Until this runs, the app uploads
-- without the check.
-- ============================================================================

alter table public.user_backups
  add column if not exists version bigint not null default 0;

commit;
